using System;
using System.Collections.Generic;
using System.IO;
using System.Threading.Tasks;
using Microsoft.Graph;
using Moq;

namespace Enterprise.MailManager.ExternalMailInterface.Testing
{
	sealed class GraphServiceClientForTest : GraphServiceClient
	{
		public GraphServiceClientForTest(IAuthenticationProvider authenticationProvider, IHttpProvider httpProvider = null) : base(authenticationProvider, httpProvider)
		{
		}

		public IUserRequestBuilder GetUserRequestBuilder()
		{
			return GraphUtils.GetUserRequestBuilder(this, (Ms365OAuth2Configuration)MailServerConfiguration.Default.GetOAuth2Configuration());
		}

		public override IUserRequestBuilder Me => GetMockMe();
		public override IGraphServiceUsersCollectionRequestBuilder Users => GetMockUsers();

		IUserRequestBuilder GetMockMe()
		{
			var (userMessagesCollectuinRequestBuilder, mailFolderMessagesCollectionRequestBuilder) = MailFolderMessagesCollectionRequestBuilder();

			var me = new Mock<IUserRequestBuilder>();
			me.Setup(u => u.MailFolders.Inbox.Messages).Returns(mailFolderMessagesCollectionRequestBuilder);
			me.Setup(u => u.Messages).Returns(userMessagesCollectuinRequestBuilder);

			return me.Object;
		}

		IGraphServiceUsersCollectionRequestBuilder GetMockUsers()
		{
			var (userMessagesCollectuinRequestBuilder, mailFolderMessagesCollectionRequestBuilder) = MailFolderMessagesCollectionRequestBuilder();
			var userRequestBuilder = new Mock<IUserRequestBuilder>();
			userRequestBuilder.Setup(u => u.RequestUrl).Returns("https://graph.microsoft.com/v1.0/users/test@email.com");
			userRequestBuilder.Setup(u => u.MailFolders.Inbox.Messages).Returns(mailFolderMessagesCollectionRequestBuilder);
			userRequestBuilder.Setup(u => u.Messages).Returns(userMessagesCollectuinRequestBuilder);

			var users = new Mock<IGraphServiceUsersCollectionRequestBuilder>();
			users.Setup(u => u["test@email.com"]).Returns(userRequestBuilder.Object);

			return users.Object;
		}

		(IUserMessagesCollectionRequestBuilder, IMailFolderMessagesCollectionRequestBuilder) MailFolderMessagesCollectionRequestBuilder()
		{
			#region messageSizeAndId

			var messageId = "cc36d7be-fe3d-4041-a836-d595f357da2b";
			var (messages, messageRequestBuilder) = GenMessage(messageId);
			var messageIds = new Mock<IMailFolderMessagesCollectionPage>();
			messageIds.Setup(m => m.Count).Returns(messages.Count);
			messageIds.Setup(m => m.GetEnumerator()).Returns(messages.GetEnumerator());

			var messageId2 = "cc36d7be-fe3d-4041-a836-d595f357da2c";
			var (messages2, messageRequestBuilder2) = GenMessage(messageId2);
			var nextMessageCollectionPage = new Mock<IMailFolderMessagesCollectionPage>();
			nextMessageCollectionPage.Setup(m => m.Count).Returns(messages2.Count);
			nextMessageCollectionPage.Setup(m => m.GetEnumerator()).Returns(messages2.GetEnumerator());
			var nextMailFolderMessagesRequest = new Mock<IMailFolderMessagesCollectionRequest>();
			nextMailFolderMessagesRequest.Setup(n => n.GetAsync(default)).Returns(Task.FromResult(nextMessageCollectionPage.Object));
			messageIds.Setup(m => m.NextPageRequest).Returns(nextMailFolderMessagesRequest.Object);

			#endregion

			var mailFolderMessagesCollectionRequestBuilder = new Mock<IMailFolderMessagesCollectionRequestBuilder>();
			mailFolderMessagesCollectionRequestBuilder.Setup(m => m.Request().Select(It.IsAny<string>()).Expand(It.IsAny<string>()).GetAsync(default)).Returns(Task.FromResult(messageIds.Object));

			#region MIME Message

			var userMessagesCollectuinRequestBuilder = new Mock<IUserMessagesCollectionRequestBuilder>();
			userMessagesCollectuinRequestBuilder.Setup(m => m[messageId]).Returns(messageRequestBuilder.Object);
			userMessagesCollectuinRequestBuilder.Setup(m => m[messageId2]).Returns(messageRequestBuilder2.Object);

			#endregion

			#region Delete Message

			var messageRequest = new Mock<IMessageRequest>();
			messageRequest.Setup(m => m.DeleteAsync(default)).Returns(Task.FromResult(0));
			messageRequestBuilder.Setup(m => m.Request()).Returns(messageRequest.Object);
			mailFolderMessagesCollectionRequestBuilder.Setup(m => m[messageId]).Returns(messageRequestBuilder.Object);

			#endregion

			return (userMessagesCollectuinRequestBuilder.Object, mailFolderMessagesCollectionRequestBuilder.Object);
		}

		(List<Message>, Mock<IMessageRequestBuilder>) GenMessage(string messageId)
		{
			#region TestMIME Message

			var content = @"";

			Stream mimeMessage = new MemoryStream(Convert.FromBase64String(content));

			#endregion

			var singleValueExtendedProperties = new List<SingleValueLegacyExtendedProperty>
			{
				new SingleValueLegacyExtendedProperty
				{
					Id = GraphMailDownloader.PidTagMessageSizeId, Value = mimeMessage.Length.ToString()
				}
			};

			var singleValueExtendedPropertiesCollectionPage = new Mock<IMessageSingleValueExtendedPropertiesCollectionPage>();
			singleValueExtendedPropertiesCollectionPage.Setup(s => s.GetEnumerator()).Returns(singleValueExtendedProperties.GetEnumerator());

			var messages = new List<Message>()
			{
				new Message { Id = messageId, SingleValueExtendedProperties = singleValueExtendedPropertiesCollectionPage.Object }
			};

			var contentRequestBuilder = new Mock<IMessageContentRequestBuilder>();

			contentRequestBuilder.Setup(c => c.Request(default).GetAsync(default, default)).Returns(Task.FromResult(mimeMessage));
			var messageRequestBuilder = new Mock<IMessageRequestBuilder>();
			messageRequestBuilder.Setup(m => m.Content).Returns(contentRequestBuilder.Object);
			return (messages, messageRequestBuilder);
		}
	}
}
